#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 1050;
int Mod;
int add_mod(int a, int b) { return a + b >= Mod ? a + b - Mod : a + b; }
int sub_mod(int a, int b) { return a - b < 0 ? a - b + Mod : a - b; }
int mul_mod(int a, int b) { return (long long)a * b % Mod; }
void combine(int &x, int y) { x = add_mod(x, y); }

int C[MAX_SIZE][MAX_SIZE], f[MAX_SIZE], g[MAX_SIZE];
int n, m;

void precompute_combinations(int n) {
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = add_mod(C[i - 1][j - 1], C[i - 1][j]);
    }
}

int main() {
    cin >> n >> m >> Mod;
    f[1] = 2; g[1] = 0;
    int limit = max(m, n - m + 1);
    precompute_combinations(limit);
    for (int i = 2; i <= m; ++i) {
        f[i] = mul_mod(f[i - 1], 2 * (i + 1));
        g[i] = mul_mod(g[i - 1], 2 * (i + 1));
        combine(g[i], mul_mod(f[i - 1], i * (i - 1)));
        for (int j = 1; j < i; ++j) {
            int k = i - j - 1;
            int c = mul_mod(C[j + k][j], j + k + 2);
            combine(f[i], mul_mod(c, mul_mod(f[j], f[k])));
            combine(g[i], mul_mod(c, mul_mod(f[j], g[k])));
            combine(g[i], mul_mod(c, mul_mod(g[j], f[k])));
            int w = j * (j + 1) / 2 + k * (k + 1) / 2;
            combine(g[i], mul_mod(mul_mod(C[j + k][j], w), mul_mod(f[j], f[k])));
        }
    }
    static int dp[MAX_SIZE][MAX_SIZE][2];
    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;
    for (int i = 0; i <= m; ++i)
        for (int j = 0; j <= m; ++j)
            for (int o = 0; o < 2; ++o) {
                int c = dp[i][j][o];
                if (c != 0) {
                    if (o == 0) {
                        for (int k = 1; k + j <= m; ++k) {
                            combine(dp[i + 1][j + k][0], mul_mod(mul_mod(c, C[j + k][k]), f[k]));
                            combine(dp[i + 1][j + k][1], mul_mod(mul_mod(c, C[j + k][k]), g[k]));
                        }
                    } else {
                        for (int k = 1; k + j <= m; ++k) {
                            combine(dp[i + 1][j + k][1], mul_mod(mul_mod(c, C[j + k][k]), f[k]));
                        }
                    }
                }
            }
    int total = 0;
    for (int i = 1; i <= m; ++i)
        combine(total, mul_mod(dp[i][m][1], C[n - m + 1][i]));
    cout << total;
    return 0;
}
